//! Independent spec tests for Subphase 3.2 `pin_input::calibration` plunger
//! filter (verification criterion 3), written from the brief without sight of
//! the implementation.
//!
//! The traces under `spec_fixtures/plunger/` hold one raw sample per 1 ms tick
//! and are regenerated by nothing: they are plain data.

use pin_input::calibration::{PlungerConfig, PlungerFilter, PlungerOutput};
use proptest::prelude::*;

const DEADZONE: f32 = 0.02;
const MIN_SPEED: f32 = 2.0;

fn trace(text: &str) -> Vec<f32> {
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| l.trim().parse::<f32>().expect("trace sample"))
        .collect()
}

fn cfg(rest_tracking_per_s: f32) -> PlungerConfig {
    PlungerConfig {
        deadzone: DEADZONE,
        rest_tracking_per_s,
        release_min_speed: MIN_SPEED,
        release_window_ms: 100,
        ..PlungerConfig::default()
    }
}

/// Runs a trace through a fresh filter, one sample per tick starting at `t0`.
fn run(cfg: PlungerConfig, t0: u64, raw: &[f32]) -> Vec<PlungerOutput> {
    let mut f = PlungerFilter::new(cfg);
    raw.iter()
        .enumerate()
        .map(|(i, r)| f.update(*r, t0 + i as u64))
        .collect()
}

fn releases(out: &[PlungerOutput]) -> Vec<(usize, f32)> {
    out.iter()
        .enumerate()
        .filter_map(|(i, o)| o.release.map(|s| (i, s)))
        .collect()
}

/// Peak forward (towards rest) speed of `raw[..=end]` in full-scale/s.
fn true_peak(raw: &[f32], end: usize) -> f32 {
    raw[..=end]
        .windows(2)
        .map(|w| (w[0] - w[1]) * 1000.0)
        .fold(0.0, f32::max)
}

/// Tick indices where the plunger re-enters the deadzone after a pull.
fn returns(raw: &[f32]) -> Vec<usize> {
    let mut v = Vec::new();
    let mut pulled = false;
    for (i, r) in raw.iter().enumerate() {
        if *r > DEADZONE {
            pulled = true;
        } else if pulled {
            pulled = false;
            v.push(i);
        }
    }
    v
}

fn assert_positions_sane(out: &[PlungerOutput]) {
    for (i, o) in out.iter().enumerate() {
        assert!(
            o.position.is_finite() && (0.0..=1.0).contains(&o.position),
            "tick {i}: position {} outside 0..=1",
            o.position
        );
        if let Some(s) = o.release {
            assert!(s.is_finite() && s > 0.0, "tick {i}: release speed {s}");
        }
    }
}

fn assert_within_5_percent(got: f32, want: f32) {
    assert!(
        (got - want).abs() <= 0.05 * want,
        "release speed {got} is not within 5 % of the true peak {want}"
    );
}

/// Asserts exactly one release, on the return tick, with the true peak speed.
fn assert_single_release(raw: &[f32], out: &[PlungerOutput]) {
    assert_positions_sane(out);
    let rel = releases(out);
    let ret = returns(raw);
    assert_eq!(ret.len(), 1, "fixture has one return stroke");
    assert_eq!(rel.len(), 1, "exactly one release expected, got {rel:?}");
    let (tick, speed) = rel[0];
    assert_eq!(
        tick, ret[0],
        "the release is reported on the tick the plunger is back within the deadzone"
    );
    assert_eq!(out[tick].position, 0.0, "back within the deadzone means position 0");
    assert_within_5_percent(speed, true_peak(raw, tick));
}

// ---------------------------------------------------------------------------
// Defaults and static response
// ---------------------------------------------------------------------------

#[test]
fn default_config_is_sane() {
    let c = PlungerConfig::default();
    assert_eq!(c.deadzone, 0.02);
    assert!(c.rest_tracking_per_s.is_finite() && c.rest_tracking_per_s >= 0.0);
    assert!(c.release_min_speed.is_finite() && c.release_min_speed > 0.0);
    assert!(c.release_window_ms > 0);
}

#[test]
fn rest_reads_zero_and_full_pull_reads_one() {
    let mut f = PlungerFilter::new(cfg(0.0));
    for t in 0..50 {
        let o = f.update(0.0, t);
        assert_eq!(o.position, 0.0);
        assert!(o.release.is_none());
    }
    // Slow pull to the end stop: monotonic, ends at ~1.
    let mut last = 0.0f32;
    for k in 1..=4000u64 {
        let raw = k as f32 / 4000.0;
        let o = f.update(raw, 50 + k);
        assert!(o.release.is_none());
        assert!(o.position >= last - 1e-6, "position fell during a pull at raw {raw}");
        assert!((0.0..=1.0).contains(&o.position));
        if raw <= DEADZONE - 1e-4 {
            assert_eq!(o.position, 0.0, "raw {raw} is inside the deadzone");
        }
        if raw >= DEADZONE + 0.01 {
            assert!(o.position > 0.0, "raw {raw} is outside the deadzone");
        }
        last = o.position;
    }
    assert!(last >= 0.97, "full pull reads {last}, expected ~1");
    let half = PlungerFilter::new(cfg(0.0)).update(0.5, 0).position;
    assert!((0.45..=0.52).contains(&half), "half pull reads {half}");
}

#[test]
fn out_of_range_raw_is_clamped() {
    let mut f = PlungerFilter::new(cfg(0.0));
    for (t, raw) in [1.5f32, 10.0, 1e30, -0.5, -10.0, -1e30, 2.0, 0.0].into_iter().enumerate() {
        let o = f.update(raw, t as u64);
        assert!(
            o.position.is_finite() && (0.0..=1.0).contains(&o.position),
            "raw {raw} -> position {}",
            o.position
        );
        if raw < 0.0 {
            assert_eq!(o.position, 0.0, "below rest reads 0");
        }
    }
}

